using System;using System.IO;using System.Linq;using System.Collections.Generic;
namespace GearLab {public static class CompoundTests {
 public static int Run(string folder){Directory.CreateDirectory(folder);var checks=new List<string>();var failures=new List<string>();Action<bool,string> c=(ok,msg)=>{if(ok)checks.Add(msg);else failures.Add(msg);};try{var t=CompoundReducer.Example();var s=TrainSolver.Solve(t,false);c(s.Valid,"numeric example: "+string.Join(";",s.Errors));if(s.Valid){c(Math.Abs(s.TotalRatio+80)<1e-9,"signed ratio -80");c(Math.Abs(s.TotalEfficiency-.49)<1e-10,"efficiency .49");c(Math.Abs(s.States[t.Stages.Last().Id].OutputTorque-.35*80*.49)<1e-8,"torque 13.72 Nm");}t.Save(Path.Combine(folder,"compound.train.json"));var read=TransmissionTrain.Read(Path.Combine(folder,"compound.train.json"));c(read.SharedHousing.Enabled,"optional model roundtrip");s=TrainSolver.Solve(read);c(s.Valid,"geometry example: "+string.Join(";",s.Errors));if(s.Valid){c(s.Scene.Model.Parts.Any(p=>p.Id=="SH_MODULE_1")&&s.Scene.Model.Parts.Any(p=>p.Id=="SH_MODULE_2"),"two modules");c(!s.Scene.Model.Parts.Any(p=>p.Id.Contains("_COUPLING")),"no legacy coupling");c(s.Scene.Model.Parts.Count(p=>p.Reference)==1,"one motor");c(s.Scene.Model.Parts.Any(p=>p.Id=="SH_JOINT_1"),"shared shaft");c(s.Compound.Support2>s.Compound.Support1,"two actual output supports reserved");c(!s.ReadyForManufacture,"preliminary construction");File.WriteAllText(Path.Combine(folder,"compound.assembly.json"),CADDocument.Serializer().Serialize(TransmissionExport.Spec(s.Scene.Model)));File.WriteAllText(Path.Combine(folder,"compound.layout.json"),CADDocument.Serializer().Serialize(s.Compound));foreach(var p in s.Scene.Model.Parts)c(p.Volume()>0,"positive volume "+p.Id);}
 foreach(string joint in new[]{"D","Spline"}){var joined=CompoundReducer.Example();joined.SharedHousing.Joint=joint;var js=TrainSolver.Solve(joined);c(js.Valid,"detachable joint "+joint+": "+string.Join(";",js.Errors));if(js.Valid)File.WriteAllText(Path.Combine(folder,"compound-"+joint+".assembly.json"),CADDocument.Serializer().Serialize(TransmissionExport.Spec(js.Scene.Model)));}
 for(int count=2;count<=4;count++){var multi=CompoundReducer.Example();while(multi.Stages.Count<count){var n=new TrainStage{Parameters=Engine.Clone(multi.Stages.Last().Parameters),Parent=multi.Stages.Last().Id};multi.Stages.Add(n);}var ms=TrainSolver.Solve(multi);c(ms.Valid,"stage count "+count+": "+string.Join(";",ms.Errors));}
 var square=CompoundReducer.Example();square.SharedHousing.Shape="Square";c(TrainSolver.Solve(square).Valid,"square envelope");
 if(s.Valid){foreach(var part in s.Scene.Model.Parts.Where(PrintExport.Candidate)){try{PrintExport.Mesh(part);}catch(Exception ex){throw new Exception(part.Id+": "+ex.Message,ex);}}CompoundExport.PrintZip(read,s,Path.Combine(folder,"compound-print.zip"));c(File.Exists(Path.Combine(folder,"compound-print.zip")),"print ZIP with BOM");for(int phase=0;phase<4;phase++){var moved=new CadAssembly();foreach(var q in s.Scene.Model.Parts){var pose=q.Placement*PartMotion.Bind(s.Scene,q).At(phase*Math.PI/2,0);moved.Parts.Add(q.WithPlacement(pose));}File.WriteAllText(Path.Combine(folder,"compound-phase-"+phase+".assembly.json"),CADDocument.Serializer().Serialize(TransmissionExport.Spec(moved)));}var jointDoc=new RobotDocument();var robotJoint=jointDoc.Add(null);RobotTrainIntegration.Apply(robotJoint,read,read.Stages.Last().Id);c(robotJoint.GearboxDiameter>=s.Compound.Diameter&&robotJoint.GearboxLength>=s.Compound.Height,"robot envelope");}
 foreach(int kind in new[]{1,2,5,6,7,8,9,10,11,12}){var bad=CompoundReducer.Example();bad.Stages[0].Parameters.Kind=kind;c(!TrainSolver.Solve(bad,false).Valid,"incompatible kind "+kind);}
 var invalid=CompoundReducer.Example();invalid.SharedHousing.Wall=double.NaN;c(!TrainSolver.Solve(invalid,false).Valid,"NaN rejected");invalid=CompoundReducer.Example();invalid.Stages[1].Parameters.Shaft=9;c(!TrainSolver.Solve(invalid,false).Valid,"shaft mismatch rejected");invalid=CompoundReducer.Example();invalid.Stages[1].Parameters.RingOutput=true;c(!TrainSolver.Solve(invalid,false).Valid,"rotating ring rejected");invalid=CompoundReducer.Example();invalid.Stages[1].Parent=null;c(!TrainSolver.Solve(invalid,false).Valid,"branch rejected");invalid=CompoundReducer.Example();invalid.Stages[1].AllowableInputTorque=.1;c(!TrainSolver.Solve(invalid,false).Valid,"next input limit checked");var legacy=TransmissionTrain.Example();c(legacy.SharedHousing==null&&TrainSolver.Solve(legacy).Valid,"legacy scene unchanged");
 }catch(Exception ex){failures.Add(ex.ToString());}File.WriteAllText(Path.Combine(folder,"compound-results.json"),CADDocument.Serializer().Serialize(new{Passed=failures.Count==0,Checks=checks.Count,Failures=failures}));return failures.Count==0?0:1;}
}}
